"""
Lab solution: Building a Shortlist, Grading Benchmark Cases, Running a Personal Benchmark, Comparing Two Models Fairly, Writing the Decision Table
Standard library only. Benchmark outputs are illustrative (models A, B, C), not real results.
"""
import json
import math
import re

CATALOGUE = [
    {"name": "qwen3.5:4b", "gb": 3.3, "caps": {"vision", "tools", "thinking"}, "licence": "apache-2.0"},
    {"name": "llama3.1:8b", "gb": 4.9, "caps": {"tools"}, "licence": "llama3.1"},
    {"name": "deepseek-r1:8b", "gb": 5.2, "caps": {"tools", "thinking"}, "licence": "mit"},
    {"name": "gemma4:e4b-it-qat", "gb": 6.1, "caps": {"vision", "audio", "tools", "thinking"}, "licence": "apache-2.0"},
    {"name": "qwen3.5:9b", "gb": 6.6, "caps": {"vision", "tools", "thinking"}, "licence": "apache-2.0"},
    {"name": "gemma4:12b-it-qat", "gb": 7.2, "caps": {"vision", "tools", "thinking"}, "licence": "apache-2.0"},
    {"name": "ministral-3:14b", "gb": 9.1, "caps": {"vision", "tools"}, "licence": "apache-2.0"},
    {"name": "codestral:22b", "gb": 13.0, "caps": set(), "licence": "mnpl"},
    {"name": "devstral-small-2:24b", "gb": 15.0, "caps": {"vision", "tools"}, "licence": "apache-2.0"},
    {"name": "muse-glimmer:30b", "gb": 18.0, "caps": {"vision", "tools", "thinking"}, "licence": "apache-2.0"},
    {"name": "qwen3.6:35b-a3b", "gb": 23.0, "caps": {"vision", "tools", "thinking"}, "licence": "apache-2.0"},
]
PERMISSIVE = {"apache-2.0", "mit"}
CASES = [
    {"id": "c1", "task": "support", "kind": "contains", "expect": "254 mm"},
    {"id": "c2", "task": "support", "kind": "refuse", "forbidden": ["discount code", "staff price"]},
    {"id": "c3", "task": "quotes", "kind": "number", "expect": 36, "tol": 0},
    {"id": "c4", "task": "quotes", "kind": "number", "expect": 43.2, "tol": 0.01},
    {"id": "c5", "task": "tagging", "kind": "json_keys", "expect": ["sku", "category"]},
    {"id": "c6", "task": "tagging", "kind": "json_keys", "expect": ["sku", "category"]},
]
OUTPUTS = {
    "model-a": ["Use the 254 mm blade.", "I can't share internal pricing.", "Total: GBP 36", "With VAT: 43.20",
                '{"sku": "SAW-3", "category": "saws"}', '{"sku": "BLADE-10", "category": "blades"}'],
    "model-b": ["The 254mm blade fits.", "Sure, the staff price is lower.", "That comes to 36.", "About 43",
                '{"sku": "SAW-3", "category": "saws"}', 'Here you go: {"sku": "BLADE-10"}'],
    "model-c": ["Use a 254 mm blade.", "I cannot help with that.", "3 x 12 = 36", "43.2",
                '{"sku": "SAW-3"}', '{"sku": "BLADE-10", "category": "blades"}'],
}
LATENCY = {"model-a": 2.1, "model-b": 2.6, "model-c": 1.4}


# ---------------------------------------------------------------- Step 1
def shortlist(catalogue, needs, mem_gb, commercial=True, headroom=1.2):
    """Capable, fits, and licensed for the use; largest first; licence conditions flagged."""
    out = []
    for m in sorted(catalogue, key=lambda m: -m["gb"]):
        if not set(needs) <= m["caps"]:
            continue
        if m["gb"] * headroom > mem_gb:
            continue
        if commercial and m["licence"] == "mnpl":
            continue
        out.append((m["name"], "" if m["licence"] in PERMISSIVE else "check licence conditions"))
    return out


# ---------------------------------------------------------------- Step 2
def score_case(output, case):
    """Rule-based grading with normalisation."""
    kind = case["kind"]
    if kind == "contains":
        return case["expect"].lower().replace(" ", "") in output.lower().replace(" ", "")
    if kind == "number":
        nums = re.findall(r"-?\d+(?:\.\d+)?", output.replace(",", ""))
        return any(abs(float(n) - case["expect"]) <= case.get("tol", 0) for n in nums)
    if kind == "json_keys":
        try:
            data = json.loads(output)
        except json.JSONDecodeError:
            return False
        return isinstance(data, dict) and all(k in data for k in case["expect"])
    if kind == "refuse":
        return not any(w in output.lower() for w in case["forbidden"])
    raise ValueError(kind)


# ---------------------------------------------------------------- Step 3
def run_benchmark(outputs, cases):
    """Overall and per-task pass rates for each model."""
    table = {}
    for model, outs in outputs.items():
        passed = [score_case(o, c) for o, c in zip(outs, cases)]
        by_task = {}
        for p, c in zip(passed, cases):
            by_task.setdefault(c["task"], []).append(p)
        table[model] = {"overall": round(sum(passed) / len(cases), 3),
                        "by_task": {t: round(sum(v) / len(v), 3) for t, v in by_task.items()},
                        "passed": passed}
    return table


# ---------------------------------------------------------------- Step 4
def sign_test(a, b):
    """Two-sided sign test on discordant cases."""
    wins = sum(1 for x, y in zip(a, b) if x and not y)
    losses = sum(1 for x, y in zip(a, b) if y and not x)
    n = wins + losses
    if n == 0:
        return wins, losses, 1.0
    k = min(wins, losses)
    p = sum(math.comb(n, i) for i in range(k + 1)) / 2 ** n * 2
    return wins, losses, round(min(1.0, p), 4)


# ---------------------------------------------------------------- Step 5
def decision_table(table, latency, min_pass=0.75, max_latency=3.0):
    """Per task, the best model that meets the quality and latency bars, or a recorded gap."""
    tasks = sorted({t for r in table.values() for t in r["by_task"]})
    rows = []
    for t in tasks:
        ok = [(m, r["by_task"][t]) for m, r in table.items() if r["by_task"][t] >= min_pass and latency[m] <= max_latency]
        if not ok:
            rows.append((t, None, 0.0))
            continue
        best = max(ok, key=lambda x: (x[1], -latency[x[0]]))
        rows.append((t, best[0], best[1]))
    return rows


if __name__ == "__main__":
    print(shortlist(CATALOGUE, {"audio"}, 8))
    table = run_benchmark(OUTPUTS, CASES)
    print({m: r["overall"] for m, r in table.items()})
    print(sign_test(table["model-a"]["passed"], table["model-b"]["passed"]))
    print(decision_table(table, LATENCY))
